        }
        const configSize = mergedComponentPropsRef?.value?.Input?.size
        if (configSize)
          return configSize
        return 'medium'
      }
    })
    const cssVarsRef = computed(() => {
      const { value: size } = mergedSizeRef
      const {
        common: { cubicBezierEaseInOut },
        self: {
          groupLabelColor,
          borderRadius,
          groupLabelTextColor,
          lineHeight,
          groupLabelBorder,
          [createKey('fontSize', size)]: fontSize,
