import { JSDOM } from 'jsdom';
import fs from 'fs';

const naiveCss = fs.readFileSync('/home/titan/Works/elm/elm-naive-ui/css/naive-ui.css', 'utf8');
const bridgeCss = fs.readFileSync('/home/titan/Works/elm/elm-naive-ui/tools/bridge.css', 'utf8');
const code = fs.readFileSync('/tmp/input-probe/elm.js', 'utf8');

const dom = new JSDOM('<!DOCTYPE html><html><head></head><body><div id="app"></div></body></html>', {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  beforeParse(window) {
    window.eval(code);
  }
});
const w = dom.window;
w.Elm.Main.init({ node: w.document.getElementById('app') });

setTimeout(() => {
  const doc = w.document;
  // attach the real stylesheets (naive-ui css + bridge), scoped under .nui-root
  const style = doc.createElement('style');
  style.textContent = naiveCss + '\n' + bridgeCss;
  doc.head.appendChild(style);

  const inputs = [...doc.querySelectorAll('.n-input')];
  console.log('n-input count:', inputs.length);
  console.log('n-input-group count:', doc.querySelectorAll('.n-input-group').length);
  console.log('n-input-group-label count:', doc.querySelectorAll('.n-input-group-label').length);

  // 1) dump the DOM tree of the first input and the clearable one
  const dump = (root, label) => {
    console.log('\n===== ' + label + ' =====');
    const walk = (n, d) => {
      if (n.nodeType !== 1) return;
      const attrs = [...n.attributes].map(a => `${a.name}="${a.value.length > 60 ? a.value.slice(0, 57) + '...' : a.value}"`).join(' ');
      console.log('  '.repeat(d) + `<${n.tagName.toLowerCase()} ${attrs}>`);
      [...n.children].forEach(c => walk(c, d + 1));
    };
    walk(root, 0);
  };
  dump(inputs[0], 'basic input');
  const clearable = inputs.find(el => el.classList.contains('n-input--round'));
  dump(clearable, 'round+clearable input');
  const ta = doc.querySelector('.n-input--textarea');
  dump(ta, 'textarea');
  dump(doc.querySelector('.n-input-group'), 'input-group');

  // 2) computed styles via the cascade
  const cs = (el, props, label) => {
    const s = w.getComputedStyle(el);
    console.log('\n-- ' + label);
    for (const p of props) console.log('   ' + p + ':', s.getPropertyValue(p));
  };
  const root0 = inputs[0];
  cs(root0, ['display', 'width', 'line-height', 'font-size', 'font-weight', 'background-color', 'border-radius', 'cursor', 'position'], 'basic .n-input root');
  const inputEl = root0.querySelector('.n-input__input-el');
  cs(inputEl, ['height', 'line-height', 'color', 'caret-color', 'width', 'padding'], 'input-el');
  const wrapper = root0.querySelector('.n-input-wrapper');
  cs(wrapper, ['display', 'flex-grow', 'padding-left', 'padding-right', 'overflow'], 'wrapper');
  const inputWrap = root0.querySelector('.n-input__input');
  cs(inputWrap, ['flex-grow', 'flex-shrink', 'flex-basis', 'position', 'overflow', 'display'], '.n-input__input');
  const border = root0.querySelector('.n-input__border');
  cs(border, ['position', 'border', 'border-radius', 'pointer-events'], 'border');
  const stateBorder = root0.querySelector('.n-input__state-border');
  cs(stateBorder, ['position', 'border-color', 'z-index'], 'state-border');
  const ph = inputs[1].querySelector('.n-input__placeholder');
  cs(ph, ['position', 'color', 'display', 'align-items', 'white-space'], 'placeholder (empty value)');
  const clearBtn = clearable.querySelector('.n-base-clear__clear');
  cs(clearBtn, ['position', 'color', 'cursor', 'font-size', 'transform'], 'clear button');
  const suffix = inputs[5].querySelector('.n-input__suffix');
  cs(suffix, ['display', 'align-items', 'line-height', 'color', 'flex-shrink', 'white-space'], 'suffix');
  const prefix = inputs[5].querySelector('.n-input__prefix');
  cs(prefix, ['margin-right'], 'prefix');
  const warn = inputs[6];
  const warnState = warn.querySelector('.n-input__state-border');
  cs(warnState, ['border'], 'warning state-border');
  cs(warn.querySelector('.n-input__input-el'), ['caret-color'], 'warning caret');
  const taEl = ta.querySelector('.n-input__textarea-el');
  cs(taEl, ['line-height', 'padding-top', 'padding-bottom', 'resize', 'white-space', 'height'], 'textarea-el');
  const label = doc.querySelector('.n-input-group-label');
  cs(label, ['display', 'background-color', 'color', 'font-size', 'height', 'line-height', 'padding'], 'group-label');
  const labelBorder = label.querySelector('.n-input-group-label__border');
  cs(labelBorder, ['position', 'border', 'border-radius'], 'group-label border');
  const group = doc.querySelector('.n-input-group');
  cs(group, ['display', 'width'], 'group');
  const small = inputs[9];
  console.log('\nsmall root style:', small.getAttribute('style').slice(0, 200));
  const tiny = inputs[10];
  console.log('tiny height var:', w.getComputedStyle(tiny).getPropertyValue('--n-height') || tiny.getAttribute('style').match(/--n-height:[^;]+/)?.[0]);

  // 3) verify style attr vars for medium
  const styleAttr = inputs[0].getAttribute('style');
  const varCount = (styleAttr.match(/--n-/g) || []).length;
  console.log('\nroot --n-* var count (medium, basic):', varCount);
  console.log('has --n-padding-left:', styleAttr.includes('--n-padding-left:12px'), '| --n-padding-right:', styleAttr.includes('--n-padding-right:12px'));
  console.log('has --n-height:34px:', styleAttr.includes('--n-height:34px'));
  console.log('has --n-font-size:14px:', styleAttr.includes('--n-font-size:14px'));
  console.log('has --n-border:', styleAttr.includes('--n-border:1px solid rgb(224, 224, 230)'));
  console.log('has --n-bezier:', styleAttr.includes('--n-bezier'));
  console.log('classes basic:', inputs[0].className);
  console.log('classes disabled:', inputs.find(e => e.classList.contains('n-input--disabled'))?.className);
  console.log('classes success-status:', inputs[8].className);
}, 300);

